using System;
using System.IO;
using System.Linq;
using AgentHands;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
public class AgentAcceptance {
 static int count;
 static void Check(bool value,string name){if(!value)throw new Exception("ACCEPTANCE FAILED: "+name);count++;Debug.Log("ACCEPTANCE PASS: "+name);}
 public static void Run(){EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);BuildAgentHands.Assets();var rt=new GestureRuntime(Resources.Load<Material>("AgentHandMaterial"));rt.Place(new Vector3(0,1.6f,0),Vector3.forward);rt.Seek(0);Check(rt.Head.activeSelf,"orb before question");var hands=UnityEngine.Object.FindObjectsByType<Transform>(FindObjectsSortMode.None).Where(x=>x.name=="Agent left hand"||x.name=="Agent right hand").ToArray();Check(hands.Length==2&&hands.All(x=>x.gameObject.activeSelf),"two hands before question");rt.SetState("thinking");rt.Seek(1);Check(rt.State=="thinking"&&hands.All(x=>x.gameObject.activeSelf),"thinking retains agent");var o=new RegisteredObject{id="box",position=new[]{0f,1.2f,.7f},size=new[]{.1f,.1f,.1f}};rt.Load(new GesturePlan{tagged="[PointObject; object:box]this",response="this",objects=new[]{o},events=new[]{new GestureEvent{id="point",targetId="box",gesture="point",hand="right",start=1,duration=1,interactivity="none"}}});rt.SetState("idle");rt.Seek(1.5f);Check(rt.State=="gesturing","active gesture state");Check(hands.All(x=>x.gameObject.activeSelf),"unused hand remains visible");var before=hands.Select(x=>x.position).ToArray();rt.Seek(2.01f);Check(hands.All(x=>x.gameObject.activeSelf)&&rt.State=="idle","return to persistent idle");Check(hands.Select((x,i)=>Vector3.Distance(x.position,before[i])).All(x=>x<1),"bounded transition");rt.Seek(.5f);Check(rt.LastInteraction=="reset-after-seek","backward seek reset");rt.Load(new GesturePlan{objects=new[]{o},events=new[]{new GestureEvent{id="bad",targetId="missing",duration=1}}});rt.Seek(.1f);Check(rt.Diagnostics.Contains("bad"),"invalid target surfaced without crashing");Check(rt.Plan.tagged==null,"raw model not invented");var temp=Path.Combine(Path.GetTempPath(),"agent-key-test-"+Guid.NewGuid());Directory.CreateDirectory(temp);try{var provider=new GeminiDirect(temp);Check(!provider.Load()&&provider.Error.Contains("Missing"),"missing key has actionable error");File.WriteAllText(Path.Combine(temp,"api_key.txt"),"   ");Check(!provider.Load()&&provider.Error.Contains("empty"),"empty key rejected");File.WriteAllText(Path.Combine(temp,"api_key.txt"),"synthetic-not-a-real-key");Check(provider.Load(),"nonempty file loads without embedding");File.WriteAllText(Path.Combine(temp,"models.json"),"{\"responseModel\":\"replacement\",\"ttsModel\":\"gemini-2.5-flash-preview-tts\"}");Check(!provider.Load()&&provider.Error.Contains("approval"),"unapproved replacement blocked");var parsed=DirectPlanParser.Parse("[PointObject; object:box]This is a box.",new[]{o},Vector3.zero,4);Check(parsed.tagged.StartsWith("[PointObject")&&parsed.response=="This is a box."&&parsed.events.Length==1,"raw tags preserved and stripped only for speech");}finally{Directory.Delete(temp,true);}Debug.Log("AGENT_ACCEPTANCE_PASSED "+count);var path=Environment.GetEnvironmentVariable("AGENT_HANDS_ACCEPTANCE");if(!string.IsNullOrEmpty(path))File.WriteAllText(path,"{\"passed\":"+count+",\"kind\":\"Unity runtime software acceptance, not physical device\"}");}
}
